command -v python3>/dev/null||exit 127;python3 -c 'from fractions import Fraction as F;import json as j,os;x=F(1,2);s=x*(x+1);N=3;P=(2,3,5,7,11,13);K=4;f="state.json";o=j.load(open(f))if os.path.exists(f)and os.path.getsize(f)else{};t=o.get("tick",0)+1;Q=lambda q:[q.numerator,q.denominator];W=lambda p,e:["pow",p,Q(e)];A=[["Root",n,["lambda","A",["HardyZ",["log","A"]]]]for n in range(1,N+1)];R=[{"n":n+1,"A":A[n],"gamma":["log",A[n]],"rho":[Q(x),["mul","i",["log",A[n]]]],"C2":["A","A^-1"]}for n in range(N)];C=[];exec("for p in P:\n r=W(p,-2*s);a=[[\"mul\",[\"sqrt\",[\"sub\",1,r]],W(p,-s*k),[\"exp\",[\"mul\",-1,\"i\",t*k,[\"log\",p]]]]for k in range(K+1)];C.append({\"p\":p,\"r\":r,\"amp\":a})");X={"model":"RIEMANN_LOG_PRODUCT_HOLOGRAM_TM","tick":t,"eq":["x=1-x","s-x^2=x","x=log(a)"],"x":Q(x),"s":Q(s),"a":["sqrt","e"],"sigma":["map","A",["div","e","A"]],"tau":["map","A",["inv","A"]],"zeros":R,"prime":C,"identities":["log(a*b)=log(a)+log(b)","tau^2=e","sigma^2=e"],"claims":{"RH_proved":False,"zero_decimals_preset":False}};b=j.dumps(X,sort_keys=True,separators=(",",":")).encode();Y={**X,"hologram":{"coeff":list(b),"reconstruct":j.loads(b.decode())==X},"limit":"P_inf=colim_t(Gamma/C2)","exact":{"float":False,"sha":False}};open(f,"w").write(j.dumps(Y,separators=(",",":")));print(j.dumps(Y,separators=(",",":")))'